#!/usr/bin/env python3
"""Lists every API route and how it checks who is calling; writes docs/security-checklist.md.
Run: python3 scripts/security-scan.py   (re-run after adding routes; a route under "NO CHECK FOUND" must be reviewed)."""
import os, re
CHECKS = [("staff session", r"getAuthenticatedUser|getSignedInUser"), ("student session", r"getAuthenticatedStudent"), ("cron secret", r"CRON_SECRET"),
          ("parent token", r"studentOfParentToken"), ("scheme access", r"schemeAccess"), ("help viewer", r"helpViewer"), ("API key", r"integrationKey|apiKey|x-api-key"),
          ("token link", r"token")]
PUBLIC = {"app/api/auth/login/route.ts": "sign-in (IP + account lock-out)", "app/api/student/login/route.ts": "student sign-in (IP + roll-number limit)",
          "app/api/auth/logout/route.ts": "sign-out", "app/api/student/logout/route.ts": "sign-out", "app/api/request-account/route.ts": "public account request (reviewed by Super User)",
          "app/api/admissions/public/route.ts": "public admission form", "app/api/error-report/route.ts": "browser error reports", "app/api/auth/sso/[provider]/start/route.ts": "SSO redirect",
          "app/api/mcq/template/route.ts": "blank template download", "app/api/faculty/course-priorities/route.ts": "retired (410)", "app/api/faculty/my-course-priorities/route.ts": "retired (410)",
          "app/api/help/articles/route.ts": "public help articles", "app/api/help/search/route.ts": "help search (scoped by viewer)", "app/api/help/feedback/route.ts": "help feedback", "app/api/help/tickets/route.ts": "help desk (checks the viewer inside)"}
rows, missing = [], []
for root, _, files in os.walk("app/api"):
    for f in files:
        if f != "route.ts": continue
        p = os.path.join(root, f); s = open(p).read()
        how = [n for n, rx in CHECKS if re.search(rx, s)]
        methods = re.findall(r"export async function (GET|POST|PUT|PATCH|DELETE)", s)
        if p in PUBLIC: how = ["public: " + PUBLIC[p]]
        if not how: missing.append(p)
        rows.append((p.replace("app/api", "/api").replace("/route.ts", ""), ",".join(methods), ", ".join(how) or "NO CHECK FOUND"))
rows.sort()
md = ["# Security checklist", "", "Generated by `scripts/security-scan.py`.", "",
      "## Controls in place", "",
      "- Passwords: salted scrypt hashes; first passwords must be changed; optional two-step verification (TOTP) for staff.",
      "- Sign-in throttling: account lock for 15 minutes after 8 wrong passwords; student roll number limited to 8 failures / 15 min; any network address limited to 30 failed sign-ins / 15 min (lib/rateLimit.ts).",
      "- Sessions: httpOnly cookies, 7-day expiry, revocable; MFA-pending sessions cannot use staff pages.",
      "- Every API route checks the caller (table below); pages check role and institute; students see only their own record; parents only through a revocable read-only link.",
      "- Results lock on approval; grade changes need a recorded request; every sign-in, approval, export, import, backup and restore is in the audit log.",
      "- Security headers: HSTS, nosniff, Referrer-Policy, X-Frame-Options SAMEORIGIN, CSP frame-ancestors/object-src, Permissions-Policy.",
      "- Sensitive data: CNIC, health / disability and counselling records are shown only to the person and the staff who handle them; backups never contain passwords or MFA secrets.",
      "- Right of access: students download all their data (/api/student/my-data); the Institute Head exports or backs up the institute (/chairman/backups).",
      "- Retention: records of students who left stay for the accreditation cycle (at least 6 years, the HEC/council audit window) and are then eligible for deletion on the institute's request; audit logs are kept 3 years.",
      "- Backups: provider daily backups plus per-institute weekly backups (8 kept) with a safe restore of missing rows.",
      "", "## To do before go-live with a university", "",
      "- [ ] Set CRON_SECRET, SUPABASE_SERVICE_ROLE_KEY, SESSION secrets in Vercel; rotate any key that was ever shared.",
      "- [ ] Turn on two-step verification for every Institute Head, Dean, HOD and Controller of Examinations.",
      "- [ ] Run a restore drill on a copy: download a backup, delete a test batch, Check, Restore missing rows.",
      "- [ ] Review the routes below marked NO CHECK FOUND (should be none).",
      "", f"## API routes ({len(rows)}; without a recognised check: {len(missing)})", "", "| Route | Methods | Caller check |", "|---|---|---|"]
md += [f"| `{r}` | {m} | {h} |" for r, m, h in rows]
os.makedirs("docs", exist_ok=True)
open("docs/security-checklist.md", "w").write("\n".join(md) + "\n")
print(len(rows), "routes;", len(missing), "without a recognised check")
for m in missing: print("  ", m)
